#!/bin/bash -ex
#
# Copyright (C) 2026 Intel Corporation
#
# SPDX-License-Identifier: MIT
#
# Generate the auto-generated parts of the Go bindings of one Level-Zero package.
# Code generation is done in the caller's directory

set -o pipefail

SCRIPT_DIR=$(dirname "$(realpath "$0")")
ROOT_DIR=$(pwd)
PACKAGE="$1"

gotool() {
    go tool -modfile "$SCRIPT_DIR/go.mod" "$@"
}

if [ -z "$PACKAGE" ] || [ ! -d "$PACKAGE" ]; then
    echo "ERROR: package <dir> argument missing or not a dir ('$PACKAGE')!" 1>&2
    exit 1
fi

# For nested packages replace '/' with '-'
CONFIG="$(echo "$PACKAGE.yml" | tr / -)"

# The name of the auto-generated main .go file, expected to match
# GENERATOR.PackageName in the c-for-go config file.
PKGNAME=$(basename "$PACKAGE")

# NOTE: -out must point at PACKAGE's parent dir
gotool c-for-go -ccincl -nostamp -out "$ROOT_DIR/$(dirname "$PACKAGE")" "$CONFIG"

cd "$PACKAGE"
if [ -f Doxyfile ]; then
    "$SCRIPT_DIR/bin/doxygen"
fi

# godefs flattens typedefs to their base type, turning ze_bool_t into uint8.
# Feed it a header copy where ze_bool_t is a struct (with the same layout/size) to keep a distinct type.
# Reuse _obj/ which is already used by godefs and cleaned at the end of this script.
GODEFS_INCLUDE=_obj/level-zero
rm -rf "$GODEFS_INCLUDE"
mkdir -p "$GODEFS_INCLUDE"
cp -r "$ROOT_DIR"/level-zero/. "$GODEFS_INCLUDE"
sed -i 's/^typedef uint8_t ze_bool_t;$/typedef struct _ze_bool_t { uint8_t value; } ze_bool_t;/' "$GODEFS_INCLUDE/ze_api.h"
# Verify that the replacement worked
grep -q "struct _ze_bool_t" "$GODEFS_INCLUDE/ze_api.h"

CFLAGS="-I$GODEFS_INCLUDE"

# Special case for sysman/exp/intel package, which needs to include the vendored headers
if [ "$PACKAGE" = "sysman/exp/intel" ]; then
    CFLAGS="$CFLAGS -I$(realpath "$ROOT_DIR/include" --relative-to .)"
fi

# shellcheck disable=SC2086     # (info): Double quote to prevent globbing and word splitting
go tool cgo -godefs -- $CFLAGS ./types.go > types.go.tmp

go -C "$SCRIPT_DIR" run ./types-mangle \
    -in-place \
    -config "$PWD/types-mangle.yaml" \
    "$PWD/types.go.tmp"
go -C "$SCRIPT_DIR" run ./types-mangle \
    -in-place \
    -config "$PWD/types-mangle-const.yaml" \
    "$PWD/const.go"

gotool goimports types.go.tmp > types.go
rm -f types.go.tmp

# Hack to replace uint with uint64 within auto-generated function prototypes.
# There is a bug in c-for-go (in the version that we're using) that causes it
# to translate uint64_t function arguments to uint.
sed -E '/^func / s/\buint\b/uint64/g' -i "$PKGNAME.go"

# Re-format generated files
gofmt -w types.go const.go

# Remove xml/ generated by doxygen
rm -rf xml/
cd -

go generate "./$PACKAGE/..."

rm -rf "$PACKAGE"/{cgo_helpers.go,_obj/}
